// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"circulating-supply":{"slug":"circulating-supply","cat":"basics","en":"Circulating supply","contentLocale":"en","term":"Circulating supply","aka":["circulating","float"],"short":"Circulating supply is the number of coins or tokens that are publicly available and moving in the market right now, excluding locked, reserved or burned tokens.","body":[["Crypto projects usually report three supply numbers. Circulating supply is what can be traded today. Total supply is everything created so far minus burned tokens. Maximum supply is the hard cap that will ever exist, if there is one. ",["Bitcoin","bitcoin"],"'s maximum is 21 million, while some tokens have no cap."],["Circulating supply is the input for ",["market capitalization","market-capitalization"],", so it shapes how big a project looks. It changes over time: it grows when locked team and investor tokens unlock, when ",["staking","staking"]," or mining rewards are issued, and it shrinks when tokens are burned or bought back."],"Data providers sometimes disagree on which wallets count as circulating, for example treasury or foundation wallets. If a project's numbers differ a lot between sites, read the project's own token documentation and check the unlock schedule."],"example":["Suppose a token has a maximum supply of 1 billion and a circulating supply of 300 million at 1 ",["USDT","usdt"],", a market cap of 300 million USDT. Next month, 50 million team tokens unlock. Circulating supply rises to 350 million, an increase of about 17 percent. If the price stayed at 1 USDT, market cap would rise to 350 million USDT, but in practice the extra supply can push the price down if demand does not grow."],"mistakes":["Confusing circulating supply with maximum supply when calculating value.","Assuming circulating supply is fixed, when unlocks and emissions can raise it every month.","Trusting a single data site without checking the project's published token allocation."],"faq":[{"q":"What is the difference between circulating supply and total supply?","a":"Circulating supply counts tokens that can be traded now. Total supply also includes tokens that exist but are locked or held in reserve."},{"q":"Why does circulating supply increase?","a":"Common reasons are scheduled unlocks for teams and investors, staking or mining rewards, and ecosystem incentive programs."},{"q":"Can circulating supply go down?","a":"Yes, when tokens are burned or bought back and removed, or when tokens are moved into long-term locks that data providers stop counting."}],"title":"What is circulating supply in crypto? Meaning","description":"Learn what circulating supply means, how it differs from total and max supply, and why unlocks change it.","related":[["market-capitalization","Market capitalization","Market capitalization is the total value of a cryptocurrency's circulating coins, calculated as the current price multiplied by the circulating supply."],["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) is a project's value if all of its tokens that will ever exist were already in circulation, calculated as the current price multiplied by the maximum or total supply."],["token-unlock","Token unlock","A token unlock is a scheduled event when previously locked tokens, usually held by the team, investors or a treasury, become free to transfer and sell, increasing circulating supply."],["token-burn","Token burn","A token burn is the permanent removal of tokens from circulation by sending them to an address that nobody can access or by destroying them through a smart contract."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"bear-market":{"slug":"bear-market","cat":"basics","en":"Bear market","contentLocale":"en","term":"Bear market","aka":["crypto winter","bearish market"],"short":"A bear market is a sustained period of falling prices and pessimistic sentiment, commonly described as a decline of 20 percent or more from a recent high.","body":[["The name comes from a bear swiping its paws downward. In crypto, bear markets can be deep: past cycles have seen ",["Bitcoin","bitcoin"]," fall more than 70 percent from its peak and many altcoins lose over 90 percent. Long bear markets are often called crypto winter."],["Common signs include lower highs and lower lows, falling ",["trading volume","trading-volume"],", negative funding rates, project shutdowns, layoffs at crypto firms and fading media attention. Sharp relief rallies of 20 to 40 percent still happen and can trap traders who think the bottom is in."],["Bear markets reward patience and risk control. Some people use ",["dollar-cost averaging","dollar-cost-averaging"]," to build long-term positions slowly, while traders may short or stay in ",["stablecoins","stablecoin"],". Whatever you do, check the counterparty: several lenders and exchanges failed during the 2022 downturn, so where you hold assets matters as much as what you hold."]],"example":["Suppose a coin falls from 100 to 30 ",["USDT","usdt"]," over a year, a 70 percent decline. To return to 100 it needs to rise about 233 percent. A person who invested 50 USDT every month during the fall would have bought more coins at lower prices: for example, 0.5 coins at 100, 1 coin at 50 and about 1.67 coins at 30, so 150 USDT buys about 3.17 coins at an average cost of roughly 47 USDT."],"mistakes":["Catching a falling price with large lump sums instead of planned, smaller entries.","Mistaking a sharp relief rally for the end of the bear market and adding leverage.","Keeping funds on a platform without checking its solvency and withdrawal history."],"faq":[{"q":"What does bearish mean?","a":"Bearish means expecting prices to fall. A trader who is bearish might sell, hold stablecoins or open a short position."},{"q":"How long do crypto bear markets last?","a":"Past crypto bear markets have lasted roughly one to two years, but there is no rule, and future ones may differ."},{"q":"What is crypto winter?","a":"Crypto winter is slang for a long, deep bear market when prices, activity and funding all stay low."}],"title":"What is a bear market in crypto? Meaning and signs","description":"Learn what a crypto bear market is, how deep declines can be and how traders manage risk when prices keep falling.","related":[["bull-market","Bull market","A bull market is a sustained period when prices rise broadly and investor confidence is high, commonly described as a gain of 20 percent or more from a recent low."],["fud","FUD","FUD, short for fear, uncertainty and doubt, describes negative news, rumours or opinions that make people worried about an asset, whether the concerns are valid or not."],["dollar-cost-averaging","Dollar-cost averaging (DCA)","Dollar-cost averaging (DCA) is a strategy of buying a fixed amount of an asset at regular intervals, regardless of price, to spread your entry over time."],["short-selling","Short selling","Short selling is a way to profit from a falling price by selling an asset you have borrowed, or opening a short contract, and buying it back later at a lower price."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"leverage":{"slug":"leverage","cat":"derivatives","en":"Leverage","contentLocale":"en","term":"Leverage","aka":["leveraged trading","multiplier"],"short":"Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses.","body":[["Leverage is shown as a multiplier such as 3x, 10x or 50x. At 10x, 1,000 ",["USDT","usdt"]," of margin controls a 10,000 USDT position. A 1% price move then changes your margin by about 10%, in either direction."],["The main risk is ",["liquidation","liquidation"],". The higher the leverage, the smaller the price move needed to wipe out your margin. At 10x, a move of roughly 10% against you, minus a buffer for ",["maintenance margin","maintenance-margin"]," and fees, ends the position. At 50x, about 2% is enough. Leverage also increases fees and funding in relation to your margin, because both are charged on the full position."],["Leverage is a tool for capital efficiency, not a way to make a bad trade good. Many experienced traders choose their ",["position size","position-sizing"]," first, based on how much they can afford to lose at the stop-loss, and only then select leverage to free up margin. Maximum leverage differs by exchange, pair and position size, and some countries cap retail leverage on crypto derivatives."]],"example":["Suppose you have 500 USDT and open a long on ",["ETH","ethereum"]," at 2,000 USDT with 20x leverage, a position of 10,000 USDT or 5 ETH. If ETH rises 3% to 2,060, you gain 5 × 60 = 300 USDT, a 60% return on margin. If ETH falls 3% to 1,940, you lose 300 USDT, 60% of your margin, and a fall of under 5% would likely trigger liquidation."],"mistakes":["Choosing leverage before deciding how much you are willing to lose on the trade.","Forgetting that fees and funding are charged on the full leveraged size.","Assuming low leverage cannot be liquidated; it can, just after a larger move."],"faq":[{"q":"What does 10x leverage mean?","a":"It means your position is ten times your margin. A 1% price move changes your margin by about 10%."},{"q":"What leverage should a beginner use?","a":"Lower leverage gives you more room before liquidation. More important than the number is sizing the position so a stop-loss costs only a small part of your account."}],"title":"What is leverage in crypto trading? Explained simply","description":"Learn how leverage works in crypto, how it multiplies gains and losses, and why higher leverage brings liquidation closer.","related":[["margin-trading","Margin trading","Margin trading is trading with funds borrowed from an exchange, using your own assets as collateral, so you can open larger positions or short-sell."],["liquidation-price","Liquidation price","The liquidation price is the mark price at which your leveraged position will be forcibly closed because your margin would fall to the maintenance margin level."],["initial-margin","Initial margin","Initial margin is the amount of collateral you must post to open a leveraged position, usually equal to the position value divided by your leverage."],["isolated-margin","Isolated margin","Isolated margin is a margin mode where each position has its own separate collateral, so a liquidation can only take the margin assigned to that position."],["position-sizing","Position sizing","Position sizing is deciding how much to put into a single trade so that, if your stop-loss is hit, you lose only a planned share of your account."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10x leverage: more money, or more risk?"},"coin":null,"tool":"/liquidations","cta":true},"auto-deleveraging":{"slug":"auto-deleveraging","cat":"derivatives","en":"Auto-deleveraging (ADL)","contentLocale":"en","term":"Auto-deleveraging (ADL)","aka":["ADL","auto deleverage"],"short":"Auto-deleveraging (ADL) is a last-resort mechanism where an exchange automatically reduces profitable opposing positions to cover a liquidation that the market and insurance fund cannot absorb.","body":[["Normally, when a position is liquidated, the exchange closes it in the market, and the ",["insurance fund","insurance-fund"]," covers any shortfall. In extreme moves, there may be no buyers or sellers at a reasonable price and the insurance fund for that ",["contract","smart-contract"]," may not be enough. ADL then steps in."],["The exchange picks traders on the opposite side of the bankrupt position and closes part or all of their positions at the bankruptcy price. Traders are ranked by profit and ",["leverage","leverage"],", so those with large unrealized profit and high leverage are first in line. Many exchanges show an ADL indicator, often as lights or a queue ranking, next to each position."],"ADL is rare on major pairs, but it can happen in crashes or on small, illiquid contracts. If it hits you, you are not liquidated; your profitable position is closed early, often at a decent price, but you lose the rest of the move. Rules, ranking formulas and how often ADL occurs differ by exchange."],"example":["Suppose a small-cap perpetual drops 40% in minutes. A large long position worth 2 million ",["USDT","usdt"]," is liquidated, but the ",["order book","order-book"]," cannot absorb it and the insurance fund for that contract holds only 300,000 USDT. You hold a short with high unrealized profit and 20x leverage, so you rank first in the ADL queue. The exchange closes 50,000 USDT of your short at the bankruptcy price, locking in that profit but ending your trade early."],"mistakes":["Thinking ADL is the same as being liquidated; it closes profitable positions, not losing ones.","Ignoring the ADL indicator on highly leveraged, very profitable positions in illiquid markets.","Assuming every exchange handles ADL with the same ranking rules."],"faq":[{"q":"Why did my profitable position get closed by the exchange?","a":"It may have been auto-deleveraged. When a liquidation cannot be filled and the insurance fund is short, the exchange reduces top-ranked profitable positions on the other side."},{"q":"How can I lower my ADL risk?","a":"Use lower leverage and take partial profits on large winning positions, which lowers your rank in the ADL queue."}],"title":"What is auto-deleveraging (ADL) in crypto futures?","description":"Learn what auto-deleveraging is, why exchanges use it after extreme liquidations and how ADL ranking works.","related":[["insurance-fund","Insurance fund","An insurance fund is a reserve an exchange keeps to cover losses when liquidated positions cannot be closed at a price good enough to repay what they owe."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."],["unrealized-pnl","Unrealized PnL","Unrealized PnL is the profit or loss on a position that is still open, calculated from your entry price and the current price, and it only becomes real when you close the position."],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Liquidation: who pressed the forced-close button?"},"coin":null,"tool":"/liquidations","cta":false},"crypto-wallet":{"slug":"crypto-wallet","cat":"wallets-security","en":"Crypto wallet","contentLocale":"en","term":"Crypto wallet","aka":["wallet","cryptocurrency wallet","digital wallet"],"short":"A crypto wallet is software or a device that stores the private keys controlling your cryptocurrency and lets you send, receive and manage it on the blockchain.","body":[["Your coins are not actually inside the wallet. They are recorded on the ",["blockchain","blockchain"],", and the wallet holds the private keys that prove you can move them. From those keys, the wallet generates public addresses you can share to receive funds."],["Wallets come in two broad types. A ",["custodial wallet","custodial-wallet"],", such as an exchange account, means a company holds the keys for you. A ",["non-custodial wallet","non-custodial-wallet"],", such as MetaMask, Phantom or a ",["hardware wallet","hardware-wallet"],", means you hold the keys yourself, usually backed up by a ",["seed phrase","seed-phrase"]," of 12 or 24 words. Wallets are also described as hot, connected to the internet, or cold, kept offline."],"Choosing a wallet is a trade-off between convenience and control. Exchange wallets are easy and offer account recovery, but you rely on the company. Self-custody removes that dependency, but losing your seed phrase means losing your funds, and nobody can reset it for you. Always check that a wallet supports the right network before sending coins to it."],"example":["Suppose you keep 2,000 ",["USDT","usdt"]," on an exchange for trading and 0.05 BTC in a hardware wallet for long-term holding. To move 500 USDT to a DeFi app, you send it from the exchange to your non-custodial wallet on a supported network, paying a withdrawal fee of a few USDT. Your hardware wallet's 24-word seed phrase, written on paper, can restore that 0.05 BTC even if the device is lost."],"mistakes":["Storing a seed phrase in screenshots, cloud notes or email.","Sending coins on a network the receiving wallet does not support.","Assuming a crypto wallet can be recovered by customer support like a bank account."],"faq":[{"q":"What is the safest type of crypto wallet?","a":"For long-term holdings, many people use a hardware wallet with a seed phrase stored offline. Safety also depends on how well you protect that backup."},{"q":"Do I need a crypto wallet if I use an exchange?","a":"Your exchange account already acts as a custodial wallet. A separate wallet is needed if you want to hold your own keys or use DeFi apps."}],"title":"What is a crypto wallet? Types and how they work","description":"Learn what a crypto wallet really stores, the difference between custodial and non-custodial, hot and cold wallets.","related":[["custodial-wallet","Custodial wallet","A custodial wallet is a crypto wallet where a third party, usually an exchange or app, holds the private keys and controls the funds on your behalf."],["non-custodial-wallet","Non-custodial wallet (self-custody wallet)","A non-custodial wallet is a crypto wallet where you alone hold the private keys or seed phrase, so no exchange or company can move, freeze or recover your funds for you."],["seed-phrase","Seed phrase (recovery phrase)","A seed phrase is a list of usually 12 or 24 ordinary words that encodes the master key of a crypto wallet, so anyone who has the words can restore the wallet and spend all of its funds."],["wallet-address","Wallet address","A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly."],["hardware-wallet","Hardware wallet","A hardware wallet is a small physical device that stores your private keys offline and signs transactions inside the device, so the keys never leave it even when it is plugged into a computer or phone."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Where are my coins? Exchange vs wallet"},"coin":null,"tool":null,"cta":false},"memo-tag":{"slug":"memo-tag","cat":"wallets-security","en":"Memo / destination tag","contentLocale":"en","term":"Memo / destination tag","aka":["memo","destination tag","tag","payment ID"],"short":"A memo or destination tag is an extra code attached to a transfer that tells an exchange which customer account should receive a deposit sent to a shared address.","body":[["Some blockchains, including XRP, Stellar (XLM), Cosmos (ATOM), EOS and TON for many exchanges, let a platform use one ",["deposit address","wallet-address"]," for many customers. To tell deposits apart, the exchange gives each user a memo, tag or comment that must be included with the transfer."],"The name varies: XRP uses destination tag, Stellar and Cosmos use memo, and some exchanges show it as tag or comment. If the deposit page shows one, it is required, even if your sending wallet labels the field optional.",["A missing or wrong memo means the coins reach the exchange but cannot be matched to you automatically. Many exchanges can credit them manually after you submit a request with the ",["transaction hash","transaction-hash"],", but it can take time and may involve a fee."]],"example":"Say you withdraw 300 XRP from one exchange to another. The receiving exchange shows a shared XRP address and a destination tag of 104582. On the sending side, you paste the address and enter 104582 in the tag field. The 300 XRP arrives and is credited to your account within minutes. If you had left the tag empty, the 300 XRP would sit in the exchange's shared wallet until support traced it.","mistakes":["Leaving the memo empty because the sending app marks the field as optional.","Reusing a memo from another exchange or an old screenshot.","Adding a memo when sending to a personal wallet that does not use one, then assuming it means something."],"faq":[{"q":"Do I need a memo when sending to my own wallet?","a":"Usually not. Personal wallets normally have their own address. Memos matter mainly when the receiver is an exchange or service using shared addresses."},{"q":"I forgot the memo. Are my coins lost?","a":"Often they can be recovered. Contact the receiving exchange with the transaction hash, amount and address; policies and fees vary."}],"title":"What is a memo or destination tag in crypto?","description":"What memo and destination tags are, which coins use them, and what to do if you send a deposit without one.","related":[["wallet-address","Wallet address","A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly."],["blockchain-network","Deposit network (chain selection)","A deposit network is the blockchain you choose to move a coin or token over when you deposit to or withdraw from an exchange, and the sending and receiving sides must use the same one."],["transaction-hash","Transaction hash (TxID)","A transaction hash, or TxID, is the unique identifier of a blockchain transaction, which you can paste into a block explorer to see its status, amount, addresses and confirmations."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Before you transfer: don't guess any of these"},"coin":null,"tool":null,"cta":false},"two-factor-authentication":{"slug":"two-factor-authentication","cat":"wallets-security","en":"Two-factor authentication (2FA)","contentLocale":"en","term":"Two-factor authentication (2FA)","aka":["2FA","two-step verification","MFA","multi-factor authentication"],"short":"Two-factor authentication (2FA) is a login and approval method that asks for a second proof, such as a code from an authenticator app or a security key, in addition to your password.","body":["A password is something you know. 2FA adds something you have, such as a phone running an authenticator app, a hardware security key, or a phone number receiving SMS codes. An attacker who steals your password still cannot log in or withdraw without the second factor.","Not all second factors are equally strong. Authenticator apps (time-based one-time passwords) and hardware security keys or passkeys are generally stronger than SMS, which can be intercepted through SIM swapping. Many exchanges let you combine several methods and require 2FA for logins, withdrawals and security changes.","Keep the backup or recovery key that an authenticator app shows during setup. Without it, a lost phone can lock you out for days while the exchange verifies your identity."],"example":["Suppose an attacker buys your email and password from a leaked database and tries to withdraw 2,000 ",["USDT","usdt"]," from your exchange account. The exchange asks for a 6-digit code that changes every 30 seconds in your authenticator app. The attacker does not have your phone, so the login fails. If you had only SMS codes and the attacker had taken over your phone number, the same attempt could have succeeded."],"mistakes":["Relying only on SMS codes when the exchange offers an authenticator app or security key.","Typing a 2FA code into a page you reached from an email or ad rather than the official app.","Not saving the authenticator backup key, then losing access when the phone is replaced."],"faq":[{"q":"Which type of 2FA is best for crypto?","a":"Hardware security keys or passkeys and authenticator apps are generally safer than SMS. Using more than one method gives you a fallback."},{"q":"Can 2FA be bypassed?","a":"Phishing sites can capture a code in real time and use it immediately. 2FA greatly reduces risk, but you still need to check that you are on the real site."}],"title":"What is 2FA? Two-factor authentication in crypto","description":"What two-factor authentication is, which 2FA methods are strongest, and how 2FA protects your exchange account.","related":[["anti-phishing-code","Anti-phishing code","An anti-phishing code is a personal word or phrase you set in your exchange account that the exchange includes in its genuine emails, so you can spot fake messages that do not contain it."],["withdrawal-whitelist","Withdrawal whitelist","A withdrawal whitelist is an exchange security setting that only allows withdrawals to addresses you have saved and approved in advance, blocking transfers to any new address."],["phishing","Phishing","Phishing is a scam where attackers impersonate a trusted exchange, wallet or person to trick you into revealing login details or a seed phrase, or into signing a transaction that hands over your funds."],["sub-account","Sub-account","A sub-account is a separate account created under your main exchange account, with its own balances and positions, used to separate strategies, bots or team members."]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"Find the real door first: don't open an account on a fake platform"},"coin":null,"tool":null,"cta":false},"withdrawal-whitelist":{"slug":"withdrawal-whitelist","cat":"wallets-security","en":"Withdrawal whitelist","contentLocale":"en","term":"Withdrawal whitelist","aka":["address whitelist","allowlist","withdrawal allowlist"],"short":"A withdrawal whitelist is an exchange security setting that only allows withdrawals to addresses you have saved and approved in advance, blocking transfers to any new address.","body":[["Once the whitelist is on, every withdrawal must go to an address in your address book. Adding a new address usually requires ",["2FA","two-factor-authentication"]," and email confirmation, and many exchanges add a waiting period before a new address can be used. Details differ by exchange."],"The value is in the delay and the extra checks. If someone gets into your account, they cannot simply send funds to their own address; they first have to add it, which triggers alerts and gives you time to react and freeze the account.","A whitelist also reduces copy-paste mistakes. When you pick a labelled saved address, you are less likely to paste a wrong or poisoned address from your history."],"example":["Suppose you whitelist two addresses: your ",["hardware wallet","hardware-wallet"]," and your account on another exchange. An attacker steals your login and session and tries to withdraw 1.2 ",["BTC","bitcoin"]," to a new address. The exchange requires the address to be added first, sends you an email and SMS, and holds new addresses for 24 hours as an illustrative policy. You see the alert, lock the account, and the 1.2 BTC never leaves."],"mistakes":["Turning the whitelist on but adding addresses copied from transaction history without checking them.","Adding an address and labelling it vaguely, so you later pick the wrong one.","Disabling the whitelist for convenience and forgetting to turn it back on."],"faq":[{"q":"Is a withdrawal whitelist worth enabling?","a":"For most users who withdraw to the same few addresses, yes. It adds friction only when you add a new address."},{"q":"Can I withdraw to a new address with the whitelist on?","a":"Yes, but you first need to add and verify it, and some exchanges make you wait before it can be used."}],"title":"What is a withdrawal whitelist? Exchange security","description":"What a withdrawal whitelist is, how it stops account thieves, and how to use saved addresses safely.","related":[["wallet-address","Wallet address","A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly."],["two-factor-authentication","Two-factor authentication (2FA)","Two-factor authentication (2FA) is a login and approval method that asks for a second proof, such as a code from an authenticator app or a security key, in addition to your password."],["address-poisoning","Address poisoning","Address poisoning is a scam where an attacker sends a tiny or zero-value transfer from an address that looks like one you use, hoping you later copy that fake address from your transaction history."],["anti-phishing-code","Anti-phishing code","An anti-phishing code is a personal word or phrase you set in your exchange account that the exchange includes in its genuine emails, so you can spot fake messages that do not contain it."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Before you transfer: don't guess any of these"},"coin":null,"tool":null,"cta":false},"crypto-backed-stablecoin":{"slug":"crypto-backed-stablecoin","cat":"stablecoins","en":"Crypto-backed stablecoin","contentLocale":"en","term":"Crypto-backed stablecoin","aka":["crypto-collateralized stablecoin","overcollateralized stablecoin"],"short":"A crypto-backed stablecoin is a stablecoin issued against crypto collateral locked in smart contracts, usually worth more than the coins created, so the token can stay near 1 USD.","body":[["Instead of keeping dollars in a bank, a crypto-backed stablecoin is minted by users who deposit assets like ",["ETH","ethereum"]," into a ",["smart contract","smart-contract"],". DAI, originally created by MakerDAO (now Sky), is the best-known example. Because crypto prices swing, the system demands overcollateralization: you must lock more value than you borrow."],["Each vault has a minimum collateral ratio. If the collateral value falls too close to that line, the vault is liquidated: the collateral is sold or auctioned to repay the ",["stablecoin","stablecoin"]," debt, and the owner usually pays a penalty. This mechanism is what keeps the coin backed."],["The upside is transparency: anyone can check collateral on-chain. The risks are sharp market crashes, oracle failures that feed wrong prices, and smart contract bugs. Some designs also hold other stablecoins or ",["tokenized real-world assets","real-world-assets"]," as part of their backing, which brings in off-chain risk."]],"example":"Suppose ETH trades at 3,000 USD and you deposit 2 ETH, worth 6,000 USD, into a vault with a 150% minimum collateral ratio. You mint 3,000 stablecoins, giving you a ratio of 200%. If ETH drops to 2,250 USD, your collateral is worth 4,500 USD and your ratio is exactly 150%, so the vault can be liquidated. To stay safe, you could repay part of the 3,000 debt or add more ETH before the price reaches that level.","mistakes":["Minting the maximum amount allowed so that a small price drop triggers liquidation.","Assuming crypto-backed means fully decentralized, without checking whether part of the reserves are centralized stablecoins or real-world assets.","Forgetting that stability fees or borrow rates accrue on the debt over time."],"faq":[{"q":"Is DAI a crypto-backed stablecoin?","a":"Yes, DAI is minted against collateral locked in smart contracts. Over time its backing has expanded beyond ETH to include other stablecoins and tokenized real-world assets."},{"q":"Why do crypto-backed stablecoins need overcollateralization?","a":"Crypto prices can fall quickly. Locking more value than the stablecoins issued gives the system a buffer to liquidate collateral before the debt becomes undercollateralized."}],"title":"What is a crypto-backed stablecoin? How DAI-style coins work","description":"How crypto-backed stablecoins work: overcollateralized vaults, collateral ratios, liquidation, and the main risks to watch.","related":[["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."],["defi-lending","DeFi lending","DeFi lending is borrowing and lending crypto through smart contracts, where lenders earn interest from a shared pool and borrowers must lock more collateral than they borrow."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."],["algorithmic-stablecoin","Algorithmic stablecoin","An algorithmic stablecoin is a stablecoin that tries to hold its peg mainly through code-driven supply changes and incentives rather than full reserves of cash or collateral."]],"lesson":null,"coin":{"slug":"dai","name":"Dai","symbol":"DAI"},"tool":null,"cta":false},"block-explorer":{"slug":"block-explorer","cat":"onchain","en":"Block explorer","contentLocale":"en","term":"Block explorer","aka":["blockchain explorer","chain explorer"],"short":"A block explorer is a website or app that lets you search a blockchain's public records, including transactions, addresses, blocks and token transfers.","body":[["Each ",["blockchain","blockchain"]," has explorers that read its data and present it in a searchable form. Etherscan is widely used for ",["Ethereum","ethereum"],", ",["mempool","mempool"],".space and others for ",["Bitcoin","bitcoin"],", Solscan for Solana and Tronscan for TRON. You paste a ",["transaction hash","transaction-hash"],", ",["wallet address","wallet-address"]," or block number, and the explorer shows what happened."],"For everyday users, the most useful job is checking a transfer. A transaction page shows the status (pending, confirmed or failed), the sending and receiving addresses, the amount, the fee paid, the block it was included in and the number of confirmations. If an exchange says it has sent your withdrawal, the transaction hash lets you verify it yourself.","Explorers only show data for their own chain. If you sent USDT on TRON, an Ethereum explorer will not find it. Many explorers also show token contracts, holder lists and labels for known addresses; treat labels as helpful hints, not guarantees, and make sure you are using the genuine explorer site, since lookalike sites exist."],"example":"Suppose you withdraw 500 USDT from an exchange to your wallet on the TRON network and it has not arrived after 20 minutes. You copy the transaction hash from your withdrawal history and paste it into a TRON explorer. The page shows status confirmed, 500 USDT sent to an address ending in 9kQ3, with 40 confirmations. Your wallet address ends in 9kQ3, so the funds have arrived on-chain and your wallet app probably just needs to refresh or add the token.","mistakes":["Searching a transaction on the wrong chain's explorer and concluding it does not exist.","Relying on a screenshot from someone else instead of checking the transaction hash yourself.","Using a lookalike explorer site from a search ad or a message instead of a known one."],"faq":[{"q":"How do I check if my crypto transfer went through?","a":"Copy the transaction hash from your wallet or exchange, open an explorer for that specific chain, and search it. The page shows whether it is pending, confirmed or failed."},{"q":"Is it safe to search my address on a block explorer?","a":"Searching does not give anyone access to your funds; blockchain data is already public. Never enter your seed phrase or private key on an explorer or any site that asks for it."}],"title":"What is a block explorer? How to check a transaction","description":"What a block explorer is and how to use one to check a crypto transfer, transaction hash, confirmations, fees and wallet balances.","related":[["transaction-hash","Transaction hash (TxID)","A transaction hash, or TxID, is the unique identifier of a blockchain transaction, which you can paste into a block explorer to see its status, amount, addresses and confirmations."],["block-confirmations","Block confirmations","Block confirmations are the number of blocks added to a blockchain since the block that includes your transaction, and exchanges wait for a set number before crediting a deposit."],["wallet-address","Wallet address","A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly."],["on-chain-analysis","On-chain analysis","On-chain analysis is the study of public blockchain data, such as transactions, wallet balances and exchange flows, to understand how a network is used and how holders behave."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"It says sent, but it never arrived. Where do you look?"},"coin":null,"tool":null,"cta":false},"travel-rule":{"slug":"travel-rule","cat":"regulation","en":"Travel rule","contentLocale":"en","term":"Travel rule","aka":["crypto travel rule","FATF travel rule","Recommendation 16"],"short":"The travel rule is an anti-money laundering requirement that makes crypto service providers share sender and recipient information when they transfer crypto for customers.","body":["The rule comes from FATF Recommendation 16, originally written for bank wire transfers and extended to virtual assets. When an exchange sends a customer's crypto to another provider, it must pass along identifying details such as the sender's name and account and the recipient's name. FATF guidance sets a threshold of USD or EUR 1,000, though countries can set lower ones.","The EU applies the travel rule from the first euro since 30 December 2024, with extra checks for transfers to self-hosted wallets above 1,000 euros. Other countries apply their own thresholds and timelines. Exchanges use messaging protocols to exchange this data with each other.","In practice, you may now see extra fields when withdrawing: the recipient's name, whether the destination is an exchange or your own wallet, and which exchange. Some transfers may be delayed or returned if the receiving provider cannot match the information. Requirements and screens differ from exchange to exchange."],"example":["Suppose you live in the EU and withdraw 1,500 ",["USDC","usdc"]," from one exchange to an account in your own name on another exchange. The sending exchange asks you to pick the destination exchange and confirm the recipient name. Because the receiving exchange's records show the same name, the transfer passes. If you instead sent 1,500 USDC to your own self-",["hosted wallet","custodial-wallet"],", the exchange might ask you to prove you control that wallet, for example by signing a message, because the amount is above 1,000 euros."],"mistakes":["Entering a different recipient name than the one on the receiving account, causing a delay or return.","Choosing exchange as the destination type when sending to a self-hosted wallet, or the reverse.","Assuming the rule only applies to large transfers when your country may apply it from the first unit."],"faq":[{"q":"Does the travel rule apply to transfers to my own wallet?","a":"It depends on the jurisdiction. In the EU, transfers to self-hosted wallets above 1,000 euros can require proof that you own or control the wallet."},{"q":"Why did my withdrawal ask for the recipient's name?","a":"Your exchange is collecting travel rule data to pass to the receiving provider. Fill it in exactly as it appears on the receiving account."}],"title":"What is the crypto travel rule? FATF rule explained","description":"What the crypto travel rule is, how FATF Recommendation 16 and EU rules work, and why withdrawals now ask for recipient details.","related":[["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."],["aml","AML (anti-money laundering)","AML (anti-money laundering) is the set of laws and internal controls that financial firms, including crypto exchanges, use to detect and prevent illegal funds from entering the system."],["vasp","VASP (virtual asset service provider)","A VASP (virtual asset service provider) is a business that exchanges, transfers, holds or manages crypto for customers and must follow anti-money laundering rules where it operates."],["withdrawal-whitelist","Withdrawal whitelist","A withdrawal whitelist is an exchange security setting that only allows withdrawals to addresses you have saved and approved in advance, blocking transfers to any new address."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Before you transfer: don't guess any of these"},"coin":null,"tool":null,"cta":false},"spot-bitcoin-etf":{"slug":"spot-bitcoin-etf","cat":"regulation","en":"Spot bitcoin ETF","contentLocale":"en","term":"Spot bitcoin ETF","aka":["bitcoin ETF","spot BTC ETF"],"short":"A spot bitcoin ETF is an exchange-traded fund that holds actual bitcoin and lets investors gain exposure to its price through a regular brokerage account.","body":[["The fund buys and stores ",["bitcoin","bitcoin"]," with a custodian, then issues shares that trade on a stock exchange. Each share represents a slice of the bitcoin the fund holds, minus fees. US spot bitcoin ETFs started trading in January 2024, and several other markets have similar products."],"A spot ETF differs from a futures ETF, which holds bitcoin futures contracts and can drift from the spot price because of rolling costs. With a spot ETF, the fund's net asset value tracks the bitcoin it actually holds. Authorised participants create and redeem shares to keep the market price close to that value.","Compared with buying bitcoin on an exchange, an ETF trades only during stock market hours, charges an annual management fee, and you cannot withdraw the bitcoin to your own wallet. In return, it fits into brokerage and retirement accounts and avoids handling private keys. Fees, tax treatment and availability depend on the fund and on your country."],"example":"Suppose a spot bitcoin ETF holds 0.0005 BTC per share and charges a 0.25% annual fee. If bitcoin trades at 80,000 USD, each share's net asset value is about 40 USD. You buy 100 shares for about 4,000 USD. Over a year, the fee reduces holdings by 0.25%, which is about 10 USD on 4,000 USD if the bitcoin price stays flat. If bitcoin rises 10% to 88,000 USD, your shares would be worth about 4,400 USD before that fee.","mistakes":["Expecting to withdraw actual bitcoin from an ETF to a personal wallet.","Ignoring the annual management fee when comparing with holding bitcoin directly.","Confusing spot ETFs with futures ETFs, which can track bitcoin less closely."],"faq":[{"q":"Is a spot bitcoin ETF the same as owning bitcoin?","a":"You get price exposure, but you own fund shares, not bitcoin. You cannot send ETF shares on the blockchain, and the fund's custodian holds the actual coins."},{"q":"When did spot bitcoin ETFs start in the US?","a":"US spot bitcoin ETFs began trading in January 2024 after regulatory approval."}],"title":"What is a spot bitcoin ETF? How it works","description":"What a spot bitcoin ETF is, how it holds real BTC, how it differs from futures ETFs and from buying bitcoin on an exchange.","related":[["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) is the first cryptocurrency, a decentralized digital money with a hard cap of 21 million coins that runs on its own proof-of-work blockchain."],["tokenized-stocks","Tokenized stocks","Tokenized stocks are blockchain tokens designed to track the price of a company's shares, usually backed one to one by real shares held by a custodian."],["custodial-wallet","Custodial wallet","A custodial wallet is a crypto wallet where a third party, usually an exchange or app, holds the private keys and controls the funds on your behalf."],["market-capitalization","Market capitalization","Market capitalization is the total value of a cryptocurrency's circulating coins, calculated as the current price multiplied by the circulating supply."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"geo-restrictions":{"slug":"geo-restrictions","cat":"regulation","en":"Geo-restrictions (restricted regions)","contentLocale":"en","term":"Geo-restrictions (restricted regions)","aka":["restricted regions","restricted jurisdictions","geo-blocking"],"short":"Geo-restrictions are the rules that stop an exchange or crypto service from offering some or all of its products to users in certain countries or regions.","body":[["Exchanges restrict regions for legal reasons: local licensing requirements, bans on certain products such as derivatives, sanctions, or simply not having permission in that market. The list of restricted regions is usually in the terms of service, and it can differ by product. A country may have access to ",["spot trading","spot-trading"]," but not futures, ",["copy trading","copy-trading"]," or earn products."],["Restrictions are enforced through ",["KYC","kyc"]," checks on nationality and residence, IP address detection and app store availability. Rules also change. When an exchange exits a country, it typically announces a deadline to close positions and withdraw funds."],"Using a VPN or false address to bypass geo-restrictions breaks most exchanges' terms. If detected, the account can be limited to withdrawal only or closed, and recovering funds may require full documentation. It is safer to choose a service that is allowed in your country of residence."],"example":["Suppose you move from Country A to Country B, where a particular exchange cannot offer derivatives. You have an open futures position with 2,000 ",["USDT","usdt"]," margin. After you update your address, the exchange gives you 30 days to close futures positions. You close the position at a 150 USDT profit, leaving 2,150 USDT, and keep using spot trading, which is still allowed in Country B."],"mistakes":["Opening an account with a VPN in a restricted region and depositing funds anyway.","Failing to update your residence after moving, which can cause problems at a later KYC review.","Assuming access to spot trading means every product of that exchange is allowed for you."],"faq":[{"q":"Why can't I access an exchange in my country?","a":"The exchange may lack a licence there, local law may restrict certain products, or sanctions may apply. Its terms of service list the restricted regions."},{"q":"Is it safe to use a VPN for a crypto exchange?","a":"Using a VPN to bypass geo-restrictions usually breaks the exchange's terms and can lead to frozen or closed accounts. Choose a service allowed where you live."}],"title":"What are geo-restrictions on crypto exchanges?","description":"Why crypto exchanges restrict some countries, how geo-restrictions are enforced, and what happens if you bypass them with a VPN.","related":[["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."],["vasp","VASP (virtual asset service provider)","A VASP (virtual asset service provider) is a business that exchanges, transfers, holds or manages crypto for customers and must follow anti-money laundering rules where it operates."],["no-kyc-exchange","No-KYC exchange","A no-KYC exchange is a platform that lets you trade crypto without verifying your identity, either fully or up to certain withdrawal limits."],["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"How does KYC work, and who should get your ID?"},"coin":null,"tool":"/exchanges","cta":false},"delisting":{"slug":"delisting","cat":"exchange-features","en":"Delisting","contentLocale":"en","term":"Delisting","aka":["delist","token delisting"],"short":"Delisting is when an exchange removes a token or trading pair, ending trading and usually setting a deadline to withdraw the remaining balances.","body":[["Exchanges delist tokens for reasons such as low ",["trading volume","trading-volume"]," and ",["liquidity","liquidity"],", a project that stopped developing, security problems, regulatory concerns or failure to meet updated listing standards. Many exchanges first add a monitoring or risk tag to a token as a warning before any decision."],["A delisting announcement normally gives dates: when trading pairs close, when deposits stop and the last day for withdrawals. Open orders are cancelled when trading ends. If the token has ",["perpetual futures","perpetual-futures"],", those contracts are usually settled earlier. After the withdrawal deadline, some exchanges ",["convert","instant-convert"]," leftover balances into a ",["stablecoin","stablecoin"],", others do not, so read each announcement."],"Prices often fall sharply after a delisting announcement because liquidity is about to shrink. If you hold the token, decide early whether to sell or move it to a wallet or another exchange that supports it, and check that the destination supports the same network."],"example":["Suppose an exchange announces that token XYZ will be delisted, with trading ending in 7 days and withdrawals closing in 30 days. You hold 5,000 XYZ worth 0.10 ",["USDT","usdt"]," each, so 500 USDT. After the news the price drops 30% to 0.07, making your holding 350 USDT. You can sell for about 350 USDT on the exchange, or withdraw the 5,000 XYZ to your own wallet for a 50 XYZ fee, leaving 4,950 XYZ to trade elsewhere."],"mistakes":["Ignoring the withdrawal deadline and losing access to the remaining balance.","Holding perpetual positions in a token being delisted without noting the earlier settlement date.","Withdrawing to a network or wallet that does not support the token."],"faq":[{"q":"What happens to my tokens when they are delisted?","a":"You can usually withdraw them until a set deadline. After that, depending on the exchange, they may be converted to a stablecoin or become inaccessible."},{"q":"Why do exchanges delist tokens?","a":"Common reasons include low liquidity, project inactivity, security incidents, regulatory issues or failing the exchange's ongoing review standards."}],"title":"What is delisting in crypto? What to do with your tokens","description":"What a crypto delisting is, why exchanges remove tokens, what the trading and withdrawal deadlines mean and how to protect balances.","related":[["token-listing","Token listing","A token listing is when an exchange adds a coin to its markets, letting users deposit, trade and withdraw it on that platform."],["liquidity","Liquidity","Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much."],["withdrawal-fee","Withdrawal fee","A withdrawal fee is the amount an exchange charges when you send crypto from your account to an external address, usually to cover the blockchain network fee."],["rug-pull","Rug pull","A rug pull is a scam where the creators of a crypto project suddenly drain its liquidity, dump their tokens or abandon it after attracting buyers, leaving the token close to worthless."]],"lesson":null,"coin":null,"tool":"/activities","cta":false}});
